#include <stdio.h>
#include <stdlib.h>
#include <inttypes.h>
#include "fftools/thread_queue.c"
int main(void){int streams,capacity,ops;av_log_set_level(AV_LOG_QUIET);while(scanf("%d %d %d",&streams,&capacity,&ops)==3){if(streams<1||streams>33||capacity<1||ops<0||ops>10000)return 2;ThreadQueue *q=tq_alloc(streams,capacity,THREAD_QUEUE_FRAMES);AVFrame *frame=av_frame_alloc();if(!q||!frame)return 3;printf("[");for(int op=0;op<ops;op++){char cmd;int index,value,ret;if(scanf(" %c %d",&cmd,&index)!=2)return 4;if(op)putchar(',');printf("{\"result\":");if(cmd=='s'){if(scanf("%d",&value)!=1)return 5;if(!(q->finished[index]&FINISHED_SEND)&&!(q->finished[index]&FINISHED_RECV)&&!av_fifo_can_write(q->fifo_stream_index))printf("\"blocked\"");else{frame->format=AV_PIX_FMT_GRAY8;frame->width=frame->height=1;if(av_frame_get_buffer(frame,32)<0)return 6;frame->data[0][0]=value;ret=tq_send(q,index,frame);printf("%d",ret);av_frame_unref(frame);}}else if(cmd=='r'){ret=tq_receive(q,&index,frame,THREAD_QUEUE_FLAG_NO_BLOCK);printf("{\"code\":");if(ret==AVERROR(EAGAIN))printf("\"again\"");else printf("%d",ret);printf(",\"stream\":%d",index);if(ret>=0)printf(",\"value\":%d",frame->data[0][0]);putchar('}');av_frame_unref(frame);}else if(cmd=='e'){tq_send_finish(q,index);printf("0");}else if(cmd=='f'){tq_receive_finish(q,index);printf("0");}else if(cmd=='c'){tq_choke(q,index);printf("0");}else return 7;
 printf(",\"state\":{\"choked\":%s,\"finished\":[",q->choked?"true":"false");for(int i=0;i<streams;i++){if(i)putchar(',');printf("%d",q->finished[i]);}printf("],\"streams\":[");size_t count=av_fifo_can_read(q->fifo_stream_index);for(size_t i=0;i<count;i++){unsigned source;if(av_fifo_peek(q->fifo_stream_index,&source,1,i)<0)return 8;if(i)putchar(',');printf("%u",source);}printf("],\"bytes\":%zu}}",count);
 }puts("]");av_frame_free(&frame);tq_free(&q);}return 0;}
